function noiseTexture(size=256){const bytes=new Uint8Array(size*size*4);let seed=37;const rnd=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};for(let i=0;i<size*size;i++){const v=128+Math.round((rnd()-.5)*60);bytes[i*4]=bytes[i*4+1]=bytes[i*4+2]=v;bytes[i*4+3]=255;}const t=new T.DataTexture(bytes,size,size,T.RGBAFormat);t.wrapS=t.wrapT=T.RepeatWrapping;t.repeat.set(70,70);t.magFilter=T.LinearFilter;t.minFilter=T.LinearMipmapLinearFilter;t.generateMipmaps=true;t.needsUpdate=true;return t;}
function box(parent,w,h,d,material,x,y,z,name='',radius=.003){const mesh=new T.Mesh(new RoundedBoxGeometry(w,h,d,2,radius),material);mesh.position.set(x,y,z);mesh.name=name;mesh.receiveShadow=true;mesh.castShadow=true;parent.add(mesh);return mesh;}
function plane(parent,w,h,mat,x,y,z){const o=new T.Mesh(new T.PlaneGeometry(w,h),mat);o.position.set(x,y,z);o.receiveShadow=true;parent.add(o);return o;}
function cylinder(parent,r,h,mat,x,y,z){const o=new T.Mesh(new T.CylinderGeometry(r,r,h,48),mat);o.position.set(x,y,z);o.castShadow=o.receiveShadow=true;parent.add(o);return o;}

