 // A small, fully modelled towel and ceramic tumbler support scale and contacts.
 const towelMat=new T.MeshStandardMaterial({color:'#d0cabc',roughness:1,bumpMap:micro,bumpScale:.00045});
 for(let i=0;i<3;i++){const t=box(scene,.092,.016,.145,towelMat,-.343,.852+i*.014,.03,'Serviette_pliee',.008);t.rotation.y=-.06;counterDecor.push({mesh:t,side:-1,inset:.057});}
