const furnitureThumbnails=new Map();let thumbnailJobs=[],thumbnailFrame=0;
function queueFurnitureThumbnail(img,type,settings){
 const key=JSON.stringify([type,settings]);if(furnitureThumbnails.has(key)){img.src=furnitureThumbnails.get(key);img.dataset.rendered3d='true';return;}
 thumbnailJobs.push({img,type,settings,key});if(!thumbnailFrame)thumbnailFrame=requestAnimationFrame(renderNextFurnitureThumbnail);
}
function renderNextFurnitureThumbnail(){thumbnailFrame=0;const job=thumbnailJobs.shift();if(!job)return;if(job.img.isConnected&&$('#add-dialog').open)try{const url=furnitureThumbnail(renderer,scene.environment,finishTextures,job.type,job.settings);furnitureThumbnails.set(job.key,url);job.img.src=url;job.img.dataset.rendered3d='true';invalidate();}catch(e){console.warn('Aperçu du modèle indisponible',job.type);}
 if(thumbnailJobs.length)thumbnailFrame=requestAnimationFrame(renderNextFurnitureThumbnail);
}
