function automaticShowerPlacement(tray,asset){tray.root.updateMatrixWorld(true);const drain=tray.root.getObjectByName('Grille_evacuation'),point=drain?drain.getWorldPosition(new T.Vector3()):tray.root.position.clone(),d=asset.dimensions||itemDimensions('tap',{use:'shower'});let best=null;for(const [index,w]of composition.room.walls.entries()){if(w.height<2)continue;const t=new T.Vector3(Math.cos(w.group.rotation.y),0,-Math.sin(w.group.rotation.y)),delta=point.clone().sub(w.start),u=delta.dot(t)*100,distance=Math.abs(delta.dot(w.normal));if(u<0||u>w.length*100)continue;if(!best||distance<best.distance)best={wall:index,u:T.MathUtils.clamp(u,d.width*50+1,w.length*100-d.width*50-1),distance};}const mixer=asset.root.getObjectByName('Mitigeur_douche');asset.root.updateMatrixWorld(true);const offset=mixer?mixer.getWorldPosition(new T.Vector3()).y*100:45;return {wall:best?.wall??tray.placement.wall,u:best?.u??tray.placement.u,height:105-offset,offset:0};}
