function applyRoomPlan(config,openings=[]){for(const raw of openings){const error=!isOpening(raw.type)?'Ouverture inconnue.':openingError(raw.type,raw.settings?.width,raw.settings?.height);if(error){$('#room-editor-status').textContent=error;placementStatus(error);return false;}}const before=collectProject(),removed=composition.items.filter(i=>isOpening(i.type));for(const o of removed)composition.remove(o.id);const cleanup=()=>removed.forEach(o=>disposeObject(o.root));if(!applyRoom(config)){const error=$('#room-status').textContent;restoreProject(before);cleanup();placementStatus(error);$('#room-editor-status').textContent=error;return false;}for(const raw of openings){const asset=makeSceneAsset(raw.type,raw.settings),result=composition.add(raw.type,asset,raw.settings,raw.placement);if(result.error||composition.move(result.item.id,raw.placement).error){if(result.error)disposeObject(asset.root);const error=result.error||'Une ouverture dépasse le mur ou chevauche un équipement.';restoreProject(before);cleanup();placementStatus(error);$('#room-editor-status').textContent=error;return false;}scene.add(result.item.root);}cleanup();renderComposition();refreshLayouts();refreshProfiles();invalidate();return true;}
