function showCabinetCombinations(total){const dialog=$('#add-dialog'),parent=$('#add-choices'),choices=cabinetCombinations(total);parent.replaceChildren();$('#add-title').textContent=total+' cm · choisir les caissons';$('#width-status').textContent='Au-delà de 120 cm : choisissez plusieurs caissons.';for(const widths of choices){const card=document.createElement('button');card.className='add-card';const title=document.createElement('strong');title.textContent=widths.join(' + ')+' cm';const detail=document.createElement('small');detail.textContent=widths.length+' caissons · modèle et finition conservés · plans séparés'+(widths.includes(40)?' · 40 cm à confirmer':'');card.append(title,detail);card.onclick=()=>{if(applyCabinetCombination(widths))dialog.close();};parent.append(card);}if(!choices.length){const note=document.createElement('p');note.textContent='Aucune combinaison pour cette largeur.';parent.append(note);}if(!dialog.open)dialog.showModal();}
