function scheduleProjectCheckpoint(){if(!journal||restoring||!state.ready||dragController?.getActive()?.dragging)return;clearTimeout(projectTimer);projectTimer=setTimeout(()=>{journal.record(collectProject());updateHistoryButtons();try{localStorage.setItem('randal-general-current-project',JSON.stringify(collectProject()));}catch{}},220);}
function updateHistoryButtons(){if(!journal)return;$('#undo').disabled=!journal.canUndo;$('#redo').disabled=!journal.canRedo;}
function undoProject(){if(!journal)return;clearTimeout(projectTimer);journal.record(collectProject());const data=journal.undo();if(data)restoreProject(data);updateHistoryButtons();}
function redoProject(){if(!journal)return;clearTimeout(projectTimer);const data=journal.redo();if(data)restoreProject(data);updateHistoryButtons();}
function initializeProjectSession(){
 if(journal)return;setWorkspace('furniture');journal=new ProjectJournal();let data,guided=false;
 try{const hash=new URLSearchParams(location.hash.slice(1)).get('projet');guided=new URLSearchParams(location.search).get('guided')==='1';data=hash?decodeProject(hash):JSON.parse(localStorage.getItem(guided?'randal-general-guided-transfer-v1':'randal-general-current-project')||'null');
  if(guided&&!data)throw Error('Le transfert de votre composition est introuvable. Revenez à l’accueil pour le relancer.');
  if(data){if(hash)localStorage.removeItem('randal-general-active-project-id-v2');if(!restoreProject(data))throw Error('La composition ne peut pas être ouverte. Vos choix restent enregistrés sur la page d’accueil.');if(guided){setView('perspective',true,true);localStorage.removeItem('randal-general-guided-transfer-v1');const url=new URL(location.href);url.searchParams.delete('guided');history.replaceState(null,'',url);}}
  else restoreProject(defaultBathroomProject());
 }catch(e){placementStatus(e.message||'Projet enregistré incompatible.');if(guided){const box=document.createElement('p');box.className='commerce-status';box.setAttribute('role','alert');box.textContent=(e.message||'Transfert indisponible.')+' Les éléments affichés ne constituent pas la configuration sélectionnée. ';const link=document.createElement('a');link.href='/';link.textContent='Revenir à ma sélection';box.append(link);document.querySelector('#settings .panel-heading').after(box);}}
 journal.seed(collectProject());updateHistoryButtons();
}
function storedProjects(){try{const data=JSON.parse(localStorage.getItem('randal-general-projects')||'[]');return Array.isArray(data)?data.slice(0,20):[];}catch{return [];}}
function captureImage(width=1920,thumbnail=false){const w=stage.clientWidth,h=stage.clientHeight,ratio=renderer.getPixelRatio(),size=new T.Vector2();renderer.getSize(size);try{const desired=thumbnail?320:width,scale=Math.min(desired/w,quality.profile.ao?4:3);renderer.setPixelRatio(scale);renderer.setSize(w,h,false);ultraPipeline?.resize(w,h,scale);if(ultraPipeline)ultraPipeline.render(.016);else renderer.render(scene,camera);return canvas.toDataURL(thumbnail?'image/webp':'image/png',.8);}finally{renderer.setPixelRatio(ratio);renderer.setSize(size.x,size.y,false);ultraPipeline?.resize(w,h,ratio);invalidate(false);}}
function saveProject(){try{const data=collectProject(),saved=saveComposition(localStorage,data,{id:localStorage.getItem(ACTIVE_ID)||null});
 try{saved.thumbnail=captureImage(320,true);const all=storedProjects(),index=all.findIndex(p=>p.id===saved.id);if(index>=0){all[index]=saved;localStorage.setItem('randal-general-projects',JSON.stringify(all));}}catch{}
 localStorage.setItem(FLOW_KEY,JSON.stringify({view:'atelier',step:4}));placementStatus('Projet enregistré sur cet appareil.');return true;
 }catch{placementStatus('Enregistrement local indisponible : exportez le projet JSON.');return false;}}

const projectDeletion=createProjectDeletion({storage:localStorage,onDeleted:()=>showProjects(),onError:()=>placementStatus('Suppression impossible : votre projet est conservé.')});
function showProjects(){const body=$('#projects-list');body.replaceChildren();for(const saved of storedProjects()){const card=document.createElement('article');card.className='project-card';if(typeof saved.thumbnail==='string'&&saved.thumbnail.startsWith('data:image/')){const image=document.createElement('img');image.src=saved.thumbnail;image.alt='Aperçu du projet';card.append(image);}const title=document.createElement('strong');title.textContent=saved.title;card.append(title);button(card,'Ouvrir',()=>{if(restoreProject(saved.data)){try{localStorage.setItem('randal-general-active-project-id-v2',saved.id);}catch{}$('#projects-dialog').close();journal.record(collectProject());updateHistoryButtons();}});const remove=button(card,'Supprimer',()=>projectDeletion.request(saved));remove.classList.add('project-delete-button');remove.dataset.deleteProject=saved.id;body.append(card);}if(!body.children.length){const p=document.createElement('p');p.textContent='Vos projets enregistrés apparaîtront ici.';body.append(p);}if(!$('#projects-dialog').open)$('#projects-dialog').showModal();}
function downloadFile(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function exportProjectFile(){downloadFile(new Blob([JSON.stringify(collectProject(),null,2)],{type:'application/json'}),'randal-general-projet.json');}
async function importProjectFile(e){try{const file=e.target.files?.[0];if(!file)return;if(file.size>100000)throw new Error('Projet trop volumineux.');if(restoreProject(JSON.parse(await file.text()))){try{localStorage.removeItem('randal-general-active-project-id-v2');}catch{}journal.record(collectProject());updateHistoryButtons();}}catch{placementStatus('Ce fichier ne peut pas être ouvert.');}e.target.value='';}
async function shareProject(){try{const url=location.origin+location.pathname+'#projet='+encodeProject(collectProject());if(navigator.share)await navigator.share({title:$('#project-title').value,url});else if(navigator.clipboard){await navigator.clipboard.writeText(url);placementStatus('Lien de configuration copié.');}else{const input=$('#share-url');input.value=url;input.hidden=false;input.select();placementStatus('Copiez ce lien pour ouvrir la même configuration sur un autre appareil.');}}catch(e){if(e.name!=='AbortError')placementStatus('Partage indisponible : exportez le projet JSON.');}}
function exportImage(){try{const data=captureImage(quality.profile.ao?3840:1920);const a=document.createElement('a');a.href=data;a.download='randal-general-composition.png';a.click();}catch{placementStatus('Export image indisponible sur ce navigateur.');}}

function centerSelectedMirror(){const item=composition?.selected;if(item?.type!=='mirror')return;const candidates=composition.items.filter(i=>i.type==='cabinet'&&i.placement.wall===item.placement.wall).sort((a,b)=>Math.abs(a.placement.u-item.placement.u)-Math.abs(b.placement.u-item.placement.u));if(!candidates.length){placementStatus('Placez un meuble sur ce mur.');return;}const c=candidates[0],result=composition.move(item.id,{...item.placement,u:c.placement.u,height:Math.min(roomScene.walls[item.placement.wall].height*100-item.dimensions.height*50-1,c.placement.height+cabinetFormat(c.settings.format).height*100+65)});placementStatus(result.error||'Miroir centré sur le meuble.');renderComposition();invalidate();}
function setTemperature(value){const k=T.MathUtils.clamp(Number(value)||5500,2700,6500);state.temperature=k;const t=k/100;let r=t<=66?255:329.6987*Math.pow(t-60,-.1332),g=t<=66?99.4708*Math.log(t)-161.1196:288.1222*Math.pow(t-60,-.0755),b=t>=66?255:t<=19?0:138.5177*Math.log(t-10)-305.0448;const color=new T.Color().setRGB(T.MathUtils.clamp(r/255,0,1),T.MathUtils.clamp(g/255,0,1),T.MathUtils.clamp(b/255,0,1),T.SRGBColorSpace);key?.color.copy(color);sun?.color.copy(color);$('#temperature').value=k;$('#temperature-value').textContent=k.toLocaleString('fr-FR')+' K';invalidate();}
function fitCompositionLights(){daylightRig?.update({room:roomScene,items:composition?.items||[],mode:state.light,profile:quality.profile,color:sun.color});}
function wireLayouts(){for(const kind of ['floor','wall']){const apply=()=>{const surface=kind==='floor'?roomScene.floor:roomScene.walls[selectedWall];surface.setLayout({...surface.layout,direction:$('#'+kind+'-direction').value,pattern:$('#'+kind+'-pattern').value,x:Number($('#'+kind+'-start-x').value)||0,y:Number($('#'+kind+'-start-y').value)||0});refreshLayouts();invalidate();};for(const field of ['direction','pattern'])$('#'+kind+'-'+field).onchange=apply;$('#'+kind+'-apply-layout').onclick=apply;}}
function refreshLayouts(){if(!roomScene)return;for(const kind of ['floor','wall']){const surface=kind==='floor'?roomScene.floor:roomScene.walls[selectedWall],l=surface.layout||{},collection=state[kind+'Collection'],formats=COLLECTIONS[collection]?.formats||[],select=$('#'+kind+'-tile-format');select.replaceChildren();for(const f of formats){const option=document.createElement('option');option.value=f.id;option.textContent=f.id.replace('x',' × ')+' cm';select.append(option);}const selected=formats.find(f=>Math.abs(f.width-(l.width||1.2))<.001&&Math.abs(f.height-(l.height||.6))<.001)||tileFormat(collection);if(selected)select.value=selected.id;select.disabled=!selected;for(const field of ['direction','pattern'])$('#'+kind+'-'+field).disabled=!selected;$('#'+kind+'-direction').value=l.direction||'horizontal';$('#'+kind+'-pattern').value=l.pattern||'straight';$('#'+kind+'-start-x').value=l.x||0;$('#'+kind+'-start-y').value=l.y||0;$('#'+kind+'-summary').textContent=(kind==='floor'?'Sol':wallLabel(selectedWall))+' · '+collection+' '+(choicesFor(collection).find(c=>c.id===state[kind])?.name||'')+(selected?' · '+selected.id.replace('x',' × ')+' cm':'');}refreshQuantities();}

function dockInspector(){const panel=$('#object-editor'),settings=$('#settings'),inScene=isMobile||document.fullscreenElement===stage||stage.classList.contains('expanded'),parent=inScene?stage:settings;if(panel.parentElement&&panel.parentElement!==parent)parent.append(panel);settings.classList.toggle('context-open',!inScene&&!panel.hidden);if(isMobile&&!panel.hidden)$('#atelier').classList.remove('mobile-sheet-open');}
function saveView(){savedViews.push({name:'Cadrage '+(savedViews.length+1),position:camera.position.toArray(),target:controls.target.toArray()});if(savedViews.length>3)savedViews.shift();savedViews.forEach((v,i)=>v.name='Cadrage '+(i+1));renderSavedViews();invalidate();}
function renderSavedViews(){const parent=$('#saved-views');parent.replaceChildren();for(const v of savedViews)button(parent,v.name,()=>{stopOrbit();viewTween=null;camera.position.fromArray(v.position);controls.target.fromArray(v.target);controls.update();invalidate(false);});}function wallLabel(index){const wall=roomScene?.walls[index];return wall?.partition===undefined?'Mur '+(index+1):'Cloison '+(wall.partition+1)+' · face '+(wall.partitionSide+1);}
function wireV18(){$('#profile-edit').onclick=()=>{profileSettings.editMode=!profileSettings.editMode;refreshProfiles();invalidate();placementStatus(profileSettings.editMode?'Cliquez un repère d’angle pour ajouter, enlever ou recolorer le profilé.':'Édition des angles terminée.');};$('#paint-custom').oninput=e=>{if(state.wallCollection!=='Peinture')return;wallFinishes[selectedWall].paintHex=e.target.value;roomScene.walls[selectedWall].material.color.set(e.target.value);invalidate();};for(const kind of ['floor','wall']){$('#'+kind+'-brand').onchange=e=>{const name=Object.keys(COLLECTIONS).find(c=>COLLECTIONS[c].brand===e.target.value);if(name)setSurfaceCollection(kind,name);};$('#'+kind+'-tile-format').onchange=e=>setTileFormat(kind,e.target.value);}$('#tile-loss').onchange=e=>{tileLoss=Math.max(0,Math.min(30,Number(e.target.value)||0));refreshQuantities();invalidate();};$('#profile-enabled').onchange=e=>{profileSettings.enabled=e.target.checked;refreshProfiles();invalidate();};$('#profile-internal').onchange=e=>{profileSettings.internalCorners=e.target.checked;refreshProfiles();invalidate();};$('#profile-color').onchange=e=>{profileSettings.color=e.target.value;refreshProfiles();invalidate();};$('#profile-selected-wall').onchange=e=>{profileSettings.walls=profileSettings.walls.filter(n=>n!==selectedWall);if(e.target.checked){profileSettings.walls.push(selectedWall);profileSettings.enabled=true;profileSettings.internalCorners=true;}refreshProfiles();invalidate();};$('#export-quantities').onclick=exportQuantities;}
function setTileFormat(kind,id){if(!['floor','wall'].includes(kind)||!roomScene)return false;const collection=state[kind+'Collection'],format=COLLECTIONS[collection]?.formats.find(f=>f.id===id);if(!format)return false;const surface=kind==='floor'?roomScene.floor:roomScene.walls[selectedWall];surface.setLayout({...surface.layout,width:format.width,height:format.height});if(kind==='wall')wallFinishes[selectedWall].format=id;refreshLayouts();invalidate();return true;}
function quantityReport(){if(!roomScene)return {rows:[],groups:[]};const floor=tileFormat(state.floorCollection,$('#floor-tile-format')?.value),rows=[quantityForSurface(roomScene.floor,{collection:state.floorCollection,color:state.floor,format:floor?.id},roomScene.floor.layout,tileLoss,'Sol')];roomScene.walls.forEach((w,i)=>{const f=wallFinishes[i],format=COLLECTIONS[f.collection]?.formats.find(f=>Math.abs(f.width-(w.layout.width||1.2))<.001&&Math.abs(f.height-(w.layout.height||.6))<.001);rows.push(...coloredQuantityRows(w,{...f,format:format?.id},w.layout,tileLoss,w.partition===undefined?'Mur '+(i+1):'Cloison '+(w.partition+1)+' · face '+(w.partitionSide+1)));});for(const item of composition?.items||[]){if(item.type!=='bath'||item.settings.apron!=='tile'||item.settings.kind==='island')continue;const collection=item.settings.apronCollection||'Creta',color=item.settings.apronColor||choicesFor(collection)[0].id;for(const [i,apron]of (item.asset.tileAprons||[]).entries())rows.push(quantityForSurface({length:i===0?item.settings.width/100:item.settings.depth/100,height:.558,tiles:apron.tiles},{collection,color,format:'60x120'},{},tileLoss,(item.label||'Baignoire')+' · tablier '+(i+1)));}return {rows,groups:summarizeQuantities(rows),profiles:profileAsset?.metres||0};}
function refreshQuantities(){if(!roomScene)return;$('#tile-loss').value=tileLoss;const report=quantityReport(),fmt=n=>Number(n).toLocaleString('fr-FR',{minimumFractionDigits:2,maximumFractionDigits:2}),zones=$('#quantity-rows'),groups=$('#quantity-groups');zones.replaceChildren();groups.replaceChildren();for(const row of report.rows){const box=document.createElement('article');box.className='quantity-card';const name=document.createElement('strong');name.textContent=row.label+' · '+row.collection;const detail=document.createElement('div');detail.textContent='Surface réelle : '+fmt(row.area)+' m²'+(row.paint?' · peinture':' · avec marge : '+fmt(row.withLoss)+' m²');box.append(name,detail);if(!row.paint){const cut=document.createElement('small');cut.textContent=row.full+' entiers + '+row.cut+' à découper · chutes théoriques '+fmt(row.cutWaste)+' m²';box.append(cut);}zones.append(box);}for(const row of report.groups){const box=document.createElement('article');box.className='quantity-card';const name=document.createElement('strong');name.textContent=row.brand+' · '+row.collection+' '+(choicesFor(row.collection).find(c=>c.id===row.color)?.name||row.color)+' · '+row.format;const detail=document.createElement('div');detail.textContent=row.boxes+' boîtes · '+row.orderPieces+' pièces · '+fmt(row.orderArea)+' m²';const note=document.createElement('small');note.textContent=row.pcsBox+' pièces / '+fmt(row.m2Box)+' m² par boîte';box.append(name,detail,note);groups.append(box);}$('#floor-quantity').textContent='Surface réelle : '+fmt(report.rows[0].area)+' m²';$('#wall-quantity').textContent='Surface réelle : '+fmt(quantityForSurface(roomScene.walls[selectedWall],wallFinishes[selectedWall]).area)+' m²';}
function refreshProfiles(){if(!roomScene)return;if(profileAsset){profileAsset.group.removeFromParent();disposeObject(profileAsset.group);}profileAsset=buildProfiles(roomScene,profileSettings,wallFinishes,composition?.items||[]);roomScene.root.add(profileAsset.group);$('#profile-enabled').checked=profileSettings.enabled;$('#profile-color').value=profileSettings.color;$('#profile-edit').textContent=profileSettings.editMode?'Terminer les angles':'Modifier les angles au clic';$('#profile-internal').checked=!!profileSettings.internalCorners;$('#profile-selected-wall').checked=profileSettings.walls.includes(selectedWall);$('#profile-summary').textContent=(profileAsset.metres||0).toLocaleString('fr-FR',{maximumFractionDigits:2})+' m · angles externes, rives et baignoires';}
function exportQuantities(){const r=quantityReport(),csv=[['Zone','Fabricant','Collection','Couleur','Format','Surface réelle m²','Avec marge m²','Entiers','Découpés','Boîtes','Pièces/boîte','m²/boîte','Surface commandée m²'],...r.rows.map(v=>[v.label,v.brand||'Peinture',v.collection,v.color,v.format||'',v.area,v.withLoss||'',v.full??'',v.cut??'',v.boxes||'',v.pcsBox||'',v.m2Box||'',v.orderArea||'']),[],['Commande groupée'],...r.groups.map(v=>['',v.brand,v.collection,v.color,v.format,v.area,v.withLoss,v.full,v.cut,v.boxes,v.pcsBox,v.m2Box,v.orderArea]),[],['Profilés aluminium (m)',r.profiles]].map(row=>row.map(v=>JSON.stringify(typeof v==='number'?Math.round(v*100)/100:v)).join(';')).join('\r\n');downloadFile(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),'randal-general-surfaces-calepinage.csv');}

