function applyGeneralPlan(item){const f=FINISHES.find(f=>f.id===item.settings.topFinish),m=item.asset.topWood;if(!f||!m)return;const tx=finishTextures[f.id];m.color.set(tx?'#fff':f.hex);m.map=tx?.front||null;m.bumpMap=tx?.frontBump||null;m.bumpScale=.0004;m.roughness=f.roughness;m.needsUpdate=true;}
